import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Agent domain docs","description":"How agents use glossaries and ADRs to keep terms and decisions aligned","frontmatter":{"title":"Agent domain docs","description":"How agents use glossaries and ADRs to keep terms and decisions aligned","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/agents/domain.md"},"headers":[],"relativePath":"docs/agents/domain.md","filePath":"docs/agents/domain.md","lastUpdated":1792347072000}`),a={name:`docs/agents/domain.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="domain-docs-for-agents" tabindex="-1">Domain docs for agents <a class="header-anchor" href="#domain-docs-for-agents" aria-label="Permalink to “Domain docs for agents”">​</a></h1><p>Use the glossary to keep domain language consistent, and check relevant ADRs before proposing or changing an architectural decision.</p><p>This repository is an ecosystem umbrella with multiple domain contexts, not a single product domain. Read <a href="./../../GLOSSARY-MAP">GLOSSARY-MAP.md</a> for their boundaries and relationships. The root <a href="./../../GLOSSARY"><code>GLOSSARY.md</code></a> covers only the Pumpkin Plugin API; add a glossary for another context only when shared project vocabulary warrants one.</p><h2 id="before-you-explore" tabindex="-1">Before you explore <a class="header-anchor" href="#before-you-explore" aria-label="Permalink to “Before you explore”">​</a></h2><ol><li>Check the repository root for <code>GLOSSARY-MAP.md</code>. If it exists, read it and then read the glossary files for the contexts relevant to your work. Otherwise, read the root <code>GLOSSARY.md</code> if it exists.</li><li>Read the ADRs in <code>docs/adr/</code> that cover the area you&#39;re working on. For a context-specific decision, check for ADRs near that context&#39;s code or docs; repository contexts don&#39;t all follow a <code>src/&lt;context&gt;/</code> layout.</li></ol><p>Missing files don&#39;t block the work. Continue without calling out their absence or proposing their creation before there&#39;s a term or decision to record. The <code>/domain-modeling</code> skill, called by <code>/grill-with-docs</code> and <code>/improve-codebase-architecture</code>, creates a glossary when a term needs recording and offers an ADR only for a choice that&#39;s hard to reverse, surprising without context, and came from a real tradeoff.</p><h2 id="common-layouts" tabindex="-1">Common layouts <a class="header-anchor" href="#common-layouts" aria-label="Permalink to “Common layouts”">​</a></h2><p>In a single-context repository, the glossary and ADRs usually sit at the root:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/</span></span>
<span class="line"><span>├── GLOSSARY.md</span></span>
<span class="line"><span>├── docs/</span></span>
<span class="line"><span>│   └── adr/</span></span>
<span class="line"><span>└── src/</span></span></code></pre></div><p>A root <code>GLOSSARY-MAP.md</code> signals a multi-context repository. It points to each context&#39;s glossary; ADRs can be system-wide or scoped to one context:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/</span></span>
<span class="line"><span>├── GLOSSARY-MAP.md</span></span>
<span class="line"><span>├── docs/adr/              # system-wide decisions</span></span>
<span class="line"><span>└── src/</span></span>
<span class="line"><span>    └── &lt;context&gt;/</span></span>
<span class="line"><span>        ├── GLOSSARY.md</span></span>
<span class="line"><span>        └── docs/adr/      # context-specific decisions</span></span></code></pre></div><h2 id="use-the-glossary-s-terms" tabindex="-1">Use the glossary&#39;s terms <a class="header-anchor" href="#use-the-glossary-s-terms" aria-label="Permalink to “Use the glossary&#39;s terms”">​</a></h2><p>When you name a domain concept in an issue title, refactor proposal, hypothesis, or test name, use the glossary&#39;s preferred term. Avoid synonyms it explicitly rules out.</p><p>If you need a concept the glossary doesn&#39;t define, check whether you&#39;re inventing a term the project doesn&#39;t use or documenting a genuine gap. Reconsider the invented term; note a real gap for the domain-modeling skill.</p><h2 id="surface-meaningful-adr-conflicts" tabindex="-1">Surface meaningful ADR conflicts <a class="header-anchor" href="#surface-meaningful-adr-conflicts" aria-label="Permalink to “Surface meaningful ADR conflicts”">​</a></h2><p>If a proposed change conflicts with an ADR strongly enough to warrant revisiting it, name the ADR and explain why. Don&#39;t list theoretical alternatives that don&#39;t create real friction.</p>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};